white',1,0,0,NULL,0,NULL,'2026-06-05 09:47:40','2026-06-05 09:47:40'),(3153,278,51,'white',1,0,0,NULL,0,NULL,'2026-06-05 09:47:40','2026-06-05 09:47:40'),(3154,278,46,'white',0,0,0,NULL,0,NULL,'2026-06-05 09:47:40','2026-06-05 09:47:40'),(3155,278,25,'colored',4,0,0,NULL,0,NULL,'2026-06-05 09:47:40','2026-06-05 09:47:40'),(3156,278,3,'colored',3,4,0,NULL,0,'asistencije ×4','2026-06-05 09:47:40','2026-06-05 09:47:40'),(3157,278,15,'colored',2,0,0,NULL,0,NULL,'2026-06-05 09:47:40','2026-06-05 09:47:40'),(3158,278,7,'colored',1,0,0,NULL,0,NULL,'2026-06-05 09:47:40','2026-06-05 09:47:40'),(3159,278,4,'colored',1,0,0,NULL,0,NULL,'2026-06-05 09:47:40','2026-06-05 09:47:40'),(3160,278,8,'colored',1,0,0,NULL,0,NULL,'2026-06-05 09:47:40','2026-06-05 09:47:40'),(3161,278,45,'colored',0,0,0,NULL,0,NULL,'2026-06-05 09:47:40','2026-06-05 09:47:40');
