--
-- Table structure for table `matches`
--

DROP TABLE IF EXISTS `matches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `matches` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `season_id` int unsigned NOT NULL,
  `match_number` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `played_at` datetime NOT NULL,
  `venue` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SC Jarac',
  `scheduled_time` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `selector_name` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `white_score` int NOT NULL DEFAULT '0',
  `colored_score` int NOT NULL DEFAULT '0',
  `result_type` enum('white_win','colored_win','draw') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draw',
  `is_counted` tinyint(1) NOT NULL DEFAULT '1',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `report` mediumtext COLLATE utf8mb4_unicode_ci,
  `reporter_name` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_matches_season` (`season_id`),
  KEY `idx_matches_played_at` (`played_at`),
  KEY `idx_matches_counted` (`is_counted`),
  CONSTRAINT `fk_matches_season` FOREIGN KEY (`season_id`) REFERENCES `seasons` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=279 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

