/*!40000 ALTER TABLE `matches` DISABLE KEYS */;
INSERT INTO `matches` VALUES (223,1,'1','2025-09-03 18:00:00','SC Jarac',NULL,'S. Đorđević',5,4,'white_win',1,NULL,'Sezona je otvorena na najbolji mogući način, veoma tvrdom utakmicom u kojoj je u bilo kom trenutku tas mogao da pretekne na bilo koju stranu. MVP prošle sezone je otvorio meč odličnim golom, Sloba izjednacava na 1:1. Ivan Diligenski u svom stilu spicerojkom iz daljine za vodjstvo Belih. Djef solo akcijom kroz noge Velinu i i Momi za izjednačenje. Opet Beli u vodjstvo nakon solo akcije prošlogodišnjeg MVP-a (a to nije Atlantid),  Šareni izjednačuju efektnim golom Ogija i zatim i prelaze u vodjstvo nakon jedne zgusnute akcije pred golom Šarenih. Zoki tri tacke izjednačava nakon dobrog solo prodora Šomija za 4:4 i taj rezultat se držao veoma teško do  minut pred kraj kada opet nakon dobrog prodora Belih Vest Hem rutinski završava u zadnjem minutu meča. Honorable mentions, Zoki M koji je odbranio neke nemoguće šanse, Draskove propuštene dve stopostotne prilike, i naravno stravično trčanje i presecanje lopti dve mašine zvane Ogi i Diligenski, zvacemo ih T800 i T1000…\nP.S. Velinov najbolji trenutak meča je bio kad sam ga pogodio u ledja loptom, dok je bio u zameni…\nPoseban krug pakla za Šomija i Velina koji su se jedan deo meča svadjali više nego sto su igrali…','S. Đorđević','2026-06-05 09:47:34','2026-06-05 09:47:34'),(224,1,'2a','2025-09-10 17:00:00','SC Jarac','17:00','S. Đorđević',9,6,'white_win',1,NULL,'Izveštaj nije pisan, a strelci dva gola (po jedan sa obe strane) ostali neubeleženi.',NULL,'2026-06-05 09:47:35','2026-06-05 09:47:35'),(225,1,'2b','2025-09-10 18:00:00','SC Jarac','18:00','S. Đorđević',2,7,'colored_win',1,NULL,NULL,NULL,'2026-06-05 09:47:35','2026-06-05 09:47:35'),(226,1,'3','2025-09-17 18:00:00','SC Jarac',NULL,'S. Đorđević',4,12,'colored_win',1,NULL,NULL,NULL,'2026-06-05 09:47:35','2026-06-05 09:47:35'),(227,1,'4','2025-09-24 18:00:00','SC Jarac',NULL,'S. Đorđević',3,8,'colored_win',1,NULL,'Šteta što bojkotujem pisanje izveštaja dok se Malo ne vrati na termin... ostaćete uskraćeni za opis evrogola, dva proturena kroz noge, dva hirurški precizna šuta sa boka iz asistencija u suprotni ugao...\nČak i Zokijeva... dva gola...\nOdličan fudbal!\nŠteta za WH...\nBeli imali sticajem okolnosti dva hendikepa: WH koji je izbačen zbog povrede (pre utakmice) i Šomija kenjatora (kenjanje zamenio dubokim uzdasima)...\nŠareni imali samo jedan henikep i on zavali dva gola!!! (yo)','N. Savić','2026-06-05 09:47:35','2026-06-05 09:47:35'),(228,1,'5','2025-10-01 18:00:00','SC Jarac',NULL,'S. Đorđević',9,4,'white_win',1,NULL,NULL,NULL,'2026-06-05 09:47:35','2026-06-05 09:47:35'),(229,1,'6','2025-10-04 16:30:00','SC Jarac','16:30','S. Đorđević',13,10,'white_win',1,NULL,NULL,NULL,'2026-06-05 09:47:35','2026-06-05 09:47:35'),(230,1,'7','2025-10-08 18:00:00','SC Jarac',NULL,'S. Ćirić',12,2,'white_win',1,NULL,'(Balać odustao uoči meča zbog leđa)\nBELI SJAJ I ŠARENI OČAJ!!!\nŠta reći, a ne zaplakati...\nPred sam meč delovalo je da su Šareni u prednosti za Kotež, ali avaj. Beli su otvorili meč sa dva gola gde je lopta skakutala po gol liniji i završila u mreži šarenih. Ćirko je svoj tim održavao u život zatrpavajući protivnički gol dalekometnim šutevima od kojih su dva završila u mreži. (Mora se napomenuti da se vodila polemika oko drugog gola).\nA onda sjaj belih i pomračenje šarenih!\nBelima je svaki šut završavao u golu, svaka šmuljava lopta je našla put u mrežu...\nMora se odati počast belima koji su igrali organizovanije, više trčali i imali Diligenskog koji je sekao svaku loptu.\nNove patike kurcu ne valjaju!','N. Savić','2026-06-05 09:47:35','2026-06-05 09:47:35'),(231,1,'8','2025-10-15 18:00:00','SC Jarac',NULL,'S. Đorđević',3,5,'colored_win',1,NULL,'ODLIČAN FUDBAL U DVORANI JARAC. REPREZENTACIVCI SRBIJE MOGU DA NAM SE SAGNU!\nPišem ovaj izveštaj, a srce me steže. Žal za ispuštenom prilikom, jer kad u 47.min ispustiš vođstvo, a potom još tri gola te dotuku... Tuga je pregolema!\nPrva 3 gola pala su u 7-8 početna minuta. Beli su inicijativu iskoristili preko dvojca Zena-Atlantid, koji su doneli svom timu prednost od 2:0. Prvo je Atlantid uposlio Zenu, a potom je Atlantid razbio prokletstvo novih patika proturajući loptu Moši kroz noge. Bundalo odmah uspeva da obezbedi priključak svom timu.\nIgrao se izričito tvrd fudbal. Beli nisu koristili svoje šanse, a onda je do izražaja počela da dolazi bolja trkačka forma šarenih. U 47.min Šareni konačno uspevaju da izjednače preko Đefa koji uspeva konačno da probije Zokija M.\nOvo kao da je demoralisalo Bele, i Šareni svoju inicijativu uspevaju da unovče sa još tri gola i vođstvo od 5:2. Beli su do kraja uspeli iz još jedne kontre da smanje na 5:3, što je i bio konačni rezultat.\nSve u svemu - odličan meč, zanimljiv i atraktivan. Đef, popuši Buljadinu!\nAtlantid 8.5 - vratio se sa dva gola\nZena 8.5 - dok je imao snage, pravio razliku na terenu\nGandra 8.5 - uvek u odličnoj formi i opasan u napadu\nŠiko 8.0 - falilo je nekih njegovih špicoka\nMali 8.5 - stub tima i ovoga puta\nZoki M. 8.0 - ministar odbrane je i ovoga puta imao dva propusta\nMladen 9.0 - stamen kao i uvek sa opasnim šutom sa distance\nDili 9.0 - možda i u najboljoj trlačkoj formi, sekao sve pasove\nĐef 9.0 - puši Buljadinu!\nMoma 8.5 - primio ga kroz noge... i dao gol\nZoki...','N. Savić','2026-06-05 09:47:35','2026-06-05 09:47:35'),(232,1,'9','2025-10-22 18:00:00','SC Jarac',NULL,'M. Nikolić',8,4,'white_win',1,NULL,'I TO SE DESILO...\nPOBEDA, prva u sezoni za Šomija!!!\nOgi definitivno MVP utakmice.\nPodela koja je i na papiru delovala da Beli odnose prevagu u trčanju, tehnici, snazi...\nBeli su poveli sa golovima sa distance Welina i Šomija. Đef uspeva da svojim golom održi svoj tim u igri. Dugo je ovaj rezultat važio, a onda Atlantid uspeva da donese izjednačenje. Ipak na drugoj strani Ogi \"srećnim\" golom odmah vraća svoj tim u vođstvo (3:2). Pored Ogija za igru je bio raspoložen povratnik na teren - Šomi je svojim golovima ukanalio Šarene.\n6:2, pa Đef smanjuje na 6:3. 7:3, Nedim smanjuje 7:4. Na kraju Beli overavaju svoju pobedu za konačnih 8:4.\nĐef spasao fudbal, ali svejedno - PUŠI KURAC!!!\nOgi 9.5 - ?????\nŠomi 9.0 - ????\nZena 9.0 - ????\nWelin 8.5 - ???\nŠika 8.0 - ??\nMoša 8.5 - ????\nNedim 8.0 - ???\nAtlantid 8.5 - ???\nĐef 9.0 - puši ga!!!\nDili 8.5 - ???\nElvedin 8.5 - dobar\nZoki M. 8.5 - ???\nZoki...','N. Savić','2026-06-05 09:47:36','2026-06-05 09:47:36'),(233,1,'10','2025-10-29 18:00:00','SC Jarac',NULL,'S. Đorđević',19,10,'white_win',1,NULL,'NE, OVO NIJE RUKOMETNI MEČ - OVO JE JARAC!!! (rockon)(inlove)\nAli treba imati u vidu i da je meč startovao u 17:40h (planiran početak bio u 17:30h). Brze izmene, brza igra, sat i 20min aktivne i pre svega atraktivne utakmice - sve to je uticalo na krajnji rezultat od 19:9 u korist Belog tima.\nGoleadu je otvorio ko drugi do Atlantid, koji je odmah na početku sa distance matirao Gnjidića i najavio još jedno golgetersko veče. Vatrogasac je iznenadio Šarene povećavši prednost svog tima na 2:0, a onda Malo daje za 3:0.\nBeli su u ovim trenucima imali igru i bili dosta opasniji, a uz to i Zoki M. je bio u svom prepoznatljivom elementu na golu.\nŠareni su ipak uspeli da načnu Bele eurogolom Elvedina (3:1)!\nAtlantid ugurava loptu Šarenima za 4:1, a Nedim na drugoj strani sa distance smanjuje na 4:2.\nNeki su Atlantidovu raspoloženost za igru u ovim trenucima nazvali \"standardnim loženjem\", na šta je on odgovorio još jednim svojim golom (6:2).\nDili održava svoj tim u priključku (6:3). A onda ponor...\nVatrogasac još jedan lep gol za 7:3... Đef 8:3...\nI kakva majstorija Atlantida za 9:3 - pas preko celog terena upasira grudima i volejom iz okreta zabija u mrežu!!!\nPa još jedan...\nPa i Zoki...\n12:3 za Bele...\n13:3 za Bele...\nElvedin još jednim eurogolom sa distance pod prećku smanjuje na 13:4.\nĐef upošljava Zokija... i opet gol! (14:4)\nJedino oružije šarenih bili su šutevi sa distance - Bundalo smanjuje na 14:5.\nA onda kreće kalsično Gnjidićevo loženje i Šareni se vraćaju... 15:8\nDo kraja Beli su pokazali klasu svoje igre i matirali Šarene odbranom, dobrim akcijama i efektnim kontrama za konačnih 19:9.\nI kao dodatak - još jedna utakmica Atlantida u ovoj sezoni na kojoj postiže 8 golova!!!','N. Savić','2026-06-05 09:47:36','2026-06-05 09:47:36'),(234,1,'11a','2025-11-05 18:00:00','SC Jarac','18:00','N. Hadžibulić',5,8,'colored_win',1,NULL,'BELI OD SJAJA DO OČAJA!\nDva istaknuta golgetera pravili su razliku samo u prvoj polovini dok se jos imalo snage. Onda su primat preuzeli trkači šarenih (Ogi i Dili) koji su hranili Nedima i WH-a.\nAtlantid je otvorio meč (koji je započet 4 na 4) maestralnim šutom sa distance iz driblinga, a potom još jednim. (2:0 za Bele)\nOgi daje prvi gol za Šarene. Malo potom koristi priliku isored gola šarenih kada otima loptu bratu rođenom i uvaljuje je u mrežu. (3:1)\nNedim smanjuje opet (3:2), a potom na drugoj strani Atlantid upošljava Šomija koji vraća dva gola prednosti. (4:2)\nKako je ostalo još dosta da se igra, a upitna kondicija belih golgetera je počela da se razotkriva - šareni su počeli da koriste konfuziju u odbrani protivničkog tima i može se reći da im je sve ulazilo. Prave seriju od 5 golova (Nedim sutnuo loptu preko gola koja pogađa Zokija M. u ruke i ulazi u gol - čisto da se zna kakve su golove davali Šareni) - 7:4.\nŠomi uspeva još jednim golom da uhvati priključak za svoj tim (7:5), ali to je bilo sve od belih jer su evidentno kondiciono totalno podbacili.\nŠareni još jednim golom postavljaju konačnih 8:5.\nSve u svemu dobar fudbal. Falile su izmene. Trebalo je razdvojiti Dilija i Ogija... Ali avaj... Ziveo Jarac!\nNedim ... - pusi ga!!!\nOgi ... - i ti ga pusi!\nDili ... - na mom ? cvili!!!\nŠika ... - ♥️\nWH ... - srećan povratak!\nŠomi... - eto vam ga vaš MVP\nAtlantid ... ?\nMalo - ♥️\nPavle - ♥️\nZoki M. - ♥️','N. Savić','2026-06-05 09:47:36','2026-06-05 09:47:36'),(235,1,'11b','2025-11-05 19:00:00','SC Jarac','19:00','S. Đorđević',7,6,'white_win',1,NULL,'Krenulo je katastrofalno, gubili Šareni 7:2, vratili se pred kraj lozenjem Gnjidica i golovima Djefa, da je trajalo još 5 minuta ko zna šta bi bilo…','S. Đorđević','2026-06-05 09:47:36','2026-06-05 09:47:36'),(236,1,'12','2025-11-12 18:00:00','SC Jarac',NULL,'N. Radosavljević / S. Đorđević',9,8,'white_win',1,NULL,'PRAVI ATRAKTIVNI JARAC!!!\nU odsustvu istaknutih trkača i odbrambenih igrača, ovaj fudbal imao je onu dobru staru notu Jarca, sa pregršt atraktivnih golova.\nŠareni su koristili odsustvo Zokija TX u svojim redovima i na startu poveli sa 2:0. Atlantid prvo matira Zenu u situaciji 1 na 1, a potom Nedim iz lepe akcije zabija.\nImali smo čast i priliku da gledamo istinsku legendu na delu - Veljavi standardno sam na drugoj strani prvo u svom stilu uspeva da umuva loptu u gol za 2:1, a potom i da dekoncentriše Nedima kojem rizičan dribling na gol liniji završava u sopstvenoj mreži (usta te!!!) - 2:2.\nBeli promašuju čak dva penala!!! Prvo Malo, a potom i WH...\nWH, već u narednoj gol prilici, hvata odbitak od koš table, pogađa i dovodi svoj tim u prvo vođstvo.\nAtlantid odmah izjednačava (3:3), a potom i Gandra preokreće na 4:3.\nWH pogađa sa distance za novo izjednačenje (4:4).\nU ovim trenucima se igralo gol za gol...\nZena ponovo svoj tim dovodi u vođstvo (5:4), Draško na drugoj strani održava svoj tim u igri (5:5).\nMalo zabija evrogol sa distance (6:5), a Zena donosi prvo osetnije vođstvo svom timu (7:5).\nGandra lepo upošljava Atlantida za 7:6.\nWH ope vraća dva gola prednosti... 8:6\nAtlantidovo ubacivanje lopte sa pola terena iskusnim Mošinim demarkiranjem i izmicanjem u pravom trenutku, žabicom završava u mreži protivnika (8:7).\nU trenucima kad su jurili priključak, Šareni prave fatalnu grešku u odbrani koja rezultira još jednim Nedimovim autogolom (Ćirko bi mu pozavideo!!!). 9:7\nAtlantid pronalazi Zokija koji postiže utešni 8. gol, a već u narednim trenucima tačno 19:00:00:00:00 začuo se prepoznatljiv krik \"KRAJ!!! KRAAAAJJJ!!!!!\"\nZena 9.0 - usta te...\nZoki M. 8.5 - standardan\nMalo 9.0 - eto ti 3 boda!\nVatrogasac 8.5 - svi živi i zdravi\nVeljavi 9.5 - istinska legenda\nWH 9.0 - odličan\nAtlantid 8.5 - šteta\nNedim 6.0 - ukanali nas\nMoša 8.0 - solidan\nGandra 9.0 - najbolji u šarenim redovima\nDK 8.5 – dobar\nZoki...','N. Savić','2026-06-05 09:47:36','2026-06-05 09:47:36'),(237,1,'13A','2025-11-19 18:00:00','SC Jarac','18:00','S. Đorđević',5,10,'colored_win',1,NULL,'VEČE DUPLOG JARCA!!!\nPrvi termin je opravdao očekivanja jer je se od prvog minuta igralo tvrdo.\nMalo u 13. minutu glavom zabada Veljacom evroautogol!!! Atlantid je imao europromašaj kad je sa nekoliko metara šutirao na prazan gol i pogodio prečku. Srećom indisponiranog Atlantoda vade saigrači - već u sledećem napadu WH upošljava Nedima za 2:0. Na drugoj strani rupe u odbrani Beli kažnjavaju sa dva gola i izjednačenje - Veljavi u svom stilu i Welina na Đefovu ass.\nIgralo se veoma tvrdo. Atlantid upošljava Dilija koji zabija sa distance. (3:2) - 18:39\nOnda na scenu stupa WH koji zabija 4 brza gola za svoj tim... (7:2)\nBeli smanjuju na 7:3 još jednom majstorijom Veljavog, ali onda Atlantid konačno postiže golove - prvi serviran na tacni od strane Nedima koji je predriblao ceo tim belih pre toga, a onda i drugi kada matira Maloa u situaciji jedan na jedan. (9:3)\nBeli smanjuju golom Đefa (9:4).\nDili još jedan zabija za 10:4, a Bundalo postavlja konačnih 10:5...\nNedim 9.0 - naš Ronaldo sa Temua\nAtlantid 8.5 - malo podbacio\nWH 9.5 - igrač utakmice!\nDraško 9.0 - fantastičan na golu\nDili 9.0 - sve pokrivao\nPavle 9.0 - najbolja odigrana utakmica u Jarcu\nĐef 8.0 - Puši ?\nBundalo 8.0 - manja aktivan nego ibače\nŠika 8.0 - solidan u porazu\nMalo 8.5 - (yo)\nWelin 8.0 - na ? te nosam!\nVeljavi 9.0 - Jokić Jarca','N. Savić','2026-06-05 09:47:36','2026-06-05 09:47:36'),(238,1,'13B','2025-11-19 19:00:00','SC Jarac','19:00','S. Đorđević',8,7,'white_win',1,NULL,'Izveštaj sa utakmice – SC Jarac, 19.11.2025, 19:00\nŠareni – Beli 8:7 (3:6)\nU pravoj maloj futsalskoj drami na terenu SC Jarac, ekipa Šarenih je posle velikog preokreta savladala Bele rezultatom 8:7, u meču koji je obilovao brzim akcijama, individualnim bravurama i karakterističnim „jarčevskim“ nadigravanjem bez predaha.\n---\n? Prvo poluvreme / početak meča\nBeli su otvorili utakmicu agresivnije i organizovanije. Već u ranoj fazi, Moša je doneo prednost preciznim udarcem, nakon odličnog dodavanja Gandre – 0:1.\nNakon toga na scenu stupa Gnjidić, koji u kratkom razmaku postiže dva gola i odvodi Bele na ubedljivih 0:3. Delovalo je da će Šareni skliznuti u katastrofu, ali tada se budi njihov glavni golgeter:\nGrêbo Tekviz smanjuje na 1:3,\nSpaskovski odmah potom na 2:3.\nIpak, Beli ponovo preuzimaju kontrolu:\nGnjidić pogađa za 2:4 (ukupno hat-trick), pa Zoki TX sa dva brza gola podiže rezultat na čak 2:6. U tom trenutku Beli deluju nadmoćno, dok Šareni traže ritam.\n---\n? Veliki povratak Šarenih\nKada su svi očekivali rutinsko privođenje meča kraju, nastaje totalni obrt.\nGrêbo Tekviz ponovo ulazi u seriju i sa dva gola vraća Šarene u život – 4:6, pa 5:6.\nZatim Spaskovski pogađa za izjednačenje 6:6, a potpuni povratak kompletira Buda, koji donosi 6:6 moment koji je probudio publiku na sve četiri strane balona.\n---\n⚪ Pokušaj Beilih – pa kazna\nU završnici, Ogi (1 gol, 2 asistencije) ponovo dovodi Bele u vođstvo – 6:7, posle dobre akcije i pokazuje da tim u belom nije rekao poslednju reč.\nAli, Šareni odgovaraju u stilu šampiona:\nU poslednjim trenucima meča, pri rezultatu 7:7, Čika Spale šalje majstorsku asistenciju,\na Grêbo Tekviz postiže svoj četvrti gol i donosi dramatičnu pobedu – 8:7!\nSve se dešava nakon duge, besmislene i bezidejne akcije Belih u kojoj je Zoki TX predugo držao loptu, praktično „čučao“ u napadu, što je Šarenima dalo savršenu šansu za kontru i nokaut.\n---\n⭐ Igrač utakmice\nGrêbo Tekviz – 4 gola (uključujući pobednički), ključni čovek preokreta.\n? Učinci\nGrêbo Tekviz – 4 gola\nSpaskovski – 3 gola\nBuda – 1 gol\nČika Spale – 1 asistencija (za gol odluke)\nGnjidić – 3 gola\nZoki TX – 2 gola, 1 asistencija\nOgi – 1 gol, 2 asistencije\nMoša – 1 gol\nGandra – 2 asistencije\nObren Miljan – 1 asistencija','M. Korunović','2026-06-05 09:47:36','2026-06-05 09:47:36'),(239,1,'14A','2025-11-26 17:00:00','SC Jarac','17:00','I. Radosavljević',3,2,'white_win',1,NULL,'? Drama u maloj dvorani: Šareni prosuli 2:0, Beli preokrenuli u velikom stilu\nU terminu od 17 sati odigrana je jedna od najuzbudljivijih utakmica jeseni u SC „Jarac“. Šareni su otvorili meč furiozno, poveli 2:0 i potpuno kontrolisali ritam, ali su Beli u drugom delu uspostavili balans, smirili igru i izveli jedan od najlepših preokreta sezone.\n---\n⏱️ Prvo poluvreme – dominacija Šarenih (0:2)\nŠareni su ušli u utakmicu agresivno i organizovano. Sredina terena radila je besprekorno, pritisak je bio visok, a lopta brzo cirkulisala.\n0:1 – Nikola Bundalo rutinski završava akciju posle asistencije Stevana, koji je iskoristio rupu u odbrani Belih i idealno ga poslužio.\n0:2 – Nikola Bundalo ponovo, ovaj put nakon duge akcije Šarenih. Asistent je najverovatnije ponovo bio Steva, mada postoji verzija zapisnika u kojoj asistenstki poen ide Malom.\nU ovom periodu Šareni su imali još dve zrele šanse za 3:0, ali su loše završnice i dobra reakcija odbrane Belih održali meč živim.\n---\n? Preokret – trenutak kada je meč otišao u drugom smeru (1:2 → 3:2)\n1:2 – Solo majstorija Đinđića – prelomni trenutak\nU trenutku kada su Šareni još delovali sveže i sigurnije, Đinđić je preuzeo odgovornost, prošao dvojicu u punom sprintu, promenio ritam i preciznim udarcem probio odbranu Šarenih.\nTaj momenat potpuno je presekao dotadašnji momentum.\n2:2 – Đinđić vraća egal\nBeli su posle gola delovali kao preporođeni. Nakon dugog napada, Gandra se ubacuje iz drugog plana, asistira Đinđiću, koji neometano loptu šalje u gol.\n3:2 – Gandra za potpuni preokret\nU završnici, kada su Šareni već izgubili ritam i energiju, Gandra postiže odlučujući pogodak na meču, uz asistenciju Spaskovskog, koji je nesebično spustio loptu.\nBeli su do kraja zadržali kontrolu, a Šareni, iako opasni u kontrama, nisu uspeli da stvore još jednu pravu šansu.\nIzveštaj: M. Korunović/chatGPT',NULL,'2026-06-05 09:47:36','2026-06-05 09:47:36'),(240,1,'14B','2025-11-26 18:00:00','SC Jarac','18:00','N. Hadžibulić',10,13,'colored_win',1,NULL,'Đorđević Stefan ×1 (asistencije ×4) (od 20. minuta)\nKorunović Momir ×1 (menjao Đorđevića do 20. minuta, glasanjem odlučeno da mu pobeda ulazi u statistiku)\nKAKO JE SAMO JEDAN PAS MOGAO DA ISPIŠE ISTORIJU... ALI NIJE, JER GA NIJE NI BILO!!!\nRealno, podela je i slutila na ovaj rezultat (jebo onog ko je prvi rekao \"na pola\"!). Statični Beli protiv eksplozivnijih Šarenih... U tom slučaju džaba i golgetera i MVP-a.\nŠareni su brzo poveli sa 4:1, a Beli su tokom celog meča bili prinuđeni da jure rezultat. Primakni se na dva gola, pa se Šareni opet odlepe. Dominirali su autogolovi (čak 3 na ovom meču).\nDolazimo do situacije na nekih 6-7 min pred kraj kada Beli uspevaju skroz da istope prednost Šarenih i dođu na samo gol zaostatka (10:11)... Beli imaju kontru i sebičluk aktuelnog MVP-a koji nije želeo da uposli Atlantida - najžešćeg konkurenta u ovoj sezoni - rezultira kažnjavanjem na drugoj strani gde Šareni matiraju Bele sa konačnih 13:10.','N. Savić','2026-06-05 09:47:36','2026-06-05 09:47:36'),(241,1,'15A','2025-12-03 17:00:00','SC Jarac','17:00','I. Radosavljević',3,3,'draw',1,NULL,NULL,NULL,'2026-06-05 09:47:36','2026-06-05 09:47:36'),(242,1,'15B','2025-12-03 18:00:00','SC Jarac','18:00','S. Đorđević',2,8,'colored_win',1,NULL,'ŠARENA RAPSODIJA U BELOM!\nIako rezultat navodi na dominaciju šarenih, do pred kraj je rezultat bio 2:2, a onda se u poslednjim trenucima desila eksplozija...\nNedim prvi postiže gol, WH izjednačuje (1:1). Šareni u novoj akciji preko Nikole B. dolaze ponovo do vođstva. Đef na drugoj strani donosi novo izjednačenje. Dugo se zadržao ovaj rezultat, a onda prvi gvozdenu zavesu na golu belih u vidu Zokija M. razbija Nikola B. (3:2). Atlantid uspešno u situaciji 1 na 1 sa Zokijem M. donosi prvo osetnije vođstvo (4:2). Nikola B. još jedanput varkom povećava vođstvo svog tima na 5:2, a potom i Nedim za 6:2. U poslednjim minutima padaju još dva gola šarenih za konačnih 8:2.','N. Savić','2026-06-05 09:47:37','2026-06-05 09:47:37'),(243,1,'16A','2025-12-10 17:00:00','SC Jarac','17:00','I. Radosavljević',5,2,'white_win',0,NULL,'Mnoštvo izmena iz drugog termina potpuno obesmislilo fudbal. Statistika nedostupna, poznato da je jedan gol dao D. Klikovac koji nije ni zaveden kao igrač u ovom terminu. Stoga se ova utakmica neće računati u broj golova po meču.','N. Radosavljević','2026-06-05 09:47:37','2026-06-05 09:47:37'),(244,1,'16B','2025-12-10 18:00:00','SC Jarac','18:00','S. Đorđević',3,8,'colored_win',0,NULL,'Mikica je posle jučerašnjeg fudbala zavrsio u gipsu i biće mesec dana. Izgleda da ima napuknuće neke kosti u ramenu.\nA nije izgledalo nista strašno.\nStatistika nedostupna, osim za Diligenskog i Klikovca, stoga se ova utakmica za ostale neće računati u broj golova po meču.','N. Radosavljević','2026-06-05 09:47:37','2026-06-05 09:47:37'),(245,1,'17A','2025-12-17 17:00:00','SC Jarac','17:00','I. Radosavljević',7,9,'colored_win',1,NULL,'Nema statističkih podataka o golovima i asistencijama sa ove utakmice, izuzev da je Igor Radosavljević postigao prvi gol u sezoni.','N. Radosavljević','2026-06-05 09:47:37','2026-06-05 09:47:37'),(246,1,'17B','2025-12-17 18:00:00','SC Jarac','18:00','S. Đorđević',14,11,'white_win',1,NULL,'GRMELO JE U JARCU!!!\nA ZA PREOKRET MOMENTUMA VAŽNO JE ZVATI SE ZOKI!\nKakav meč! Kakav praznik fudbala!!! Evrogolovi, majstorije, preokreti, EVROPROMAŠAJEVI...\nAtlantid je od starta pokazao raspoloženost i maestralno matirao Zokija već u prvoj kontri. Šareni odmah izjednačavaju preko Šomija. Atlantid još jednom  majstorijom pogađa mrežu, dok je Zoki TX loptu ispratio samo pogledom. WH odmah donosi novo izjednačenje. Atlantid u ovom trenucima kao da je igrao simultanku protiv Šarenih te još jednim golom donosi novu prednost svom timu (3:2).\nOnda dolazi totalni preokret šarenih koji sa 3 gola dolaze do prednosti od 5:3. Beli golom mlađanog Nikole smanjaju na 5:4. Bundalo u ovim trenucima pravi razliku i Šareni se odlepljuju na 7:4. Beli uspevaju da uhvate priključak (7:6), a onda Šareni još jednom dodaju gas i odlepljuju se na 10:6.\nDolazimo do dva ključna trenutka i totalnog preokreta momentuma!!!\nPrvi se dešava pred golom Belih kada Zoki TX promašuje prazan gol. Beli uspevaju da postignu brzi gol nakon toga (10:7), a u jednoj od narednih kontri Zoki M. nakon sjajne odbrane kreće u napad i sa pola terena postiže evrogol za 10:8. Đef smanjuje na 10:9, a Atlantid donosi novo izjednačenje i totalni povratak u meč! 10:10...\nBeli koriste situaciju na terenu gde su Šareni u potpunosti demoralisani i sa 3 nova gola nastavljaju seriju od ukupno 7:0 - rezultat na tabeli 13:10.\nŠomiju se nakon pregleda vara priznaje gol za 13:11, ali Nikola na ass Atlantida postavlja konačnih 14:11.\nAtlantid 9.5 - meč za anale\nDili 9.0 - čovek leteo po terenu\nNikola 9.0 - mladost i znanje!!!\nĐef 9.0 - kičma tima\nĆirko 8.5 - odličan povratak!\nZoki M. 9.0 - čovek mit, legenda!\nŠomi 8.0 - gotovo neprimetan na terenu... Eto vam ga vaš MVP!\nWH 8.5 - solidan\nBundalo 9.0 - ali džaba...\nNedim 8.0 - spakovan u džep\nMali 8.0 - trud i stamenost, ali...\nZoki...','N. Savić','2026-06-05 09:47:37','2026-06-05 09:47:37'),(247,1,'18A','2025-12-24 17:00:00','SC Jarac','17:00','I. Radosavljević',8,2,'white_win',1,NULL,NULL,NULL,'2026-06-05 09:47:37','2026-06-05 09:47:37'),(248,1,'18B','2025-12-24 18:00:00','SC Jarac','18:00','S. Đorđević',5,8,'colored_win',1,NULL,'MEČ PREPUN UZBUĐENJA, PREKIDA I AKCIJE!\nBELI SRAMOTNI U PORAZU!\nMeč je započet direktnim sudarom možda i najvećih rivala u istoriji Jarca. Atlantid u prvom napadu majstorskom varkom protura loptu Šomiju kroz noge za  prvo vođstvo (1:0). Ubrzo Atlantid povećava vođstvo na 2:0, ali na drugoj strani Šomi baca odbranu šarenih, upošljava Dilija koji smanjuje na 2:1. Atlantid još jednim preciznim pogotkom u suprtoni ugao vraća vođstvo na dva gola razlike (3:1).\nWH smanjuje na 3:2, a onda u igru ulazi Zoki...\nUnprvoj situaciji 1 na 1 sa Atlantidom mislio je da se dobro pozicionirao... Samo je mislio... Lopta je nonšalantno plasirana pored njega u mrežu za 4:2.\nŠomi smanjuje na 4:3.\nNedimu se poništava gol.\nDolazimo do prvog prekida usled gašenja reflektora u sali (svega 2 bila u funkciji). Nakon dužeg prekida i delimičnog paljenja ostatka reflektora igra je nastavljenja. Beli uspevaju da izjednače autogolom DK (4:4).\nPonovo dolazi do prekida...\nOvog puta kraćeg, jer su se svi usaglasili za nastavak igre.\nNedim pogađa za 5:4, a WH još jedanput izjednačava rezultat (5:5).\nBeli su tražili penal (veoma diskutabilan) jer je Nedim leđima držao loptu na gol liniji, koji Zoki TX ne pretvara u gol.\nNedim kažnjava ovo još jednim golom za novo vođstvo. DK povećava vođstvo na 7:5, a Atlantid cementira krajnjih 8:5.\nBeli su poraz teško podneli, ali treba napomemuti da su uslovi bili isti za oba tima, a pritom su Šareni bili ti koji si prekidima gubili momentum.\nIdemo dalje! (muscle)\nAtlantid 9.0 - nastavlja golgetersku seriju\nMladen B. 8.5 - odličan na obe strane\nĆirko 8.5 - odličan povratak uz dosta promašenih gol prilika\nNedim 8.5 - manje kenjao sa loptom nego inače, ali i dalje kenjao\nDK 8.5 - odličan pre svega u odbrani i na golu\nOgi 9.0 - vidno umoran nakon prvog termina, ali opet maestralan i sveprisutan\nDili 8.5 - svetla tačka\nĐef 8.0 - puši ?\nŠomi 8.0 - njah\nWH 8.5 - solidan\nMoma 8.0 - (yo)\nZoki...\nNapomena: Igrači Belih S. Đorđević, M. Nikolić i M. Korunović uložili su prigovor na stavljanje ove utakmice u statistiku, smatrajući da nestanak struje pri rezultatu 4:4 dovodi regularnost meča u pitanje.','N. Savić','2026-06-05 09:47:37','2026-06-05 09:47:37'),(249,1,'19','2025-12-30 17:00:00','SC Jarac','17:00','S. Đorđević',4,3,'white_win',1,NULL,'TRI GOLA ZA DVA MVP-A I ZOKIJA...\nATOMSKI TEMPO! PREOKRET U ZADNJI ČAS I ŽAL ŠARENIH!!!\nUtakmica dostojna spektakla za kraj godina i da sublimira sve u samo jednom meču. MVP trka, odbrana, trčanje (sem Zokija...),  atraktivni golovi i old school Jarac.\nMeč je krenuo veoma tvrdo. Atlantid je uspeo da matira Zokija M. golom groz noge u jednoj od brojnih situacija 1 na 1, a u kojim je (sem u navedenoj) Zoki M. izlazio kao apsolutni pobednik.\nŠomi je povisio na 2:0 iz lepe akcije šarenih. Dugo je ovaj rezultat bio na tabli, vise od pola sata, a onda je WH pogodio iz nemogućeg ugla za 2:1. Šomi iz još jedne dobre akcije svog tima pogađa za novu prednost od 2 gola svog tima (3:1 | 17:45h).\nWH ponovo smanjuje na 3:2.\nU poslednjim minutima meča prvo Gnjidić srećno pogađa za izjednačenje i kada su svi mislili da će se utakmica završiti nerešeno, WH frljavim šutom i nikad sporijom loptom (slow-mo) uspeva sa distance da prevari Momu kojem lopta prolazi kroz noge i završava u mreži. Beli, koji prvih 35min meča nisu mogli da postignu gol, dolaze do prvog vođstva u poslednjem minuta meča.\nOstale je tek toliko vremena za potpuno razočarenje šarenih i žalom za propuštenim prilikama i ispuštenom trijumfu.\nOvako Beli ulaze nešto srećniji u Novu 2026. godinu...\nSve u svemu - zaista odlična tekma!!! Ipak - ĐEF PUŠI KURAC!!!\nWH 9.0 - maestralna partija\nOgi 9.0 - trcao ko lud.\nObren 9.0 - Ogi 2.0\nGnjidic 9.0 - stari dobri Gnjidic\nZoki M. 9.5 - branio kao lud\nVujadin 9.0 - \'bem te u\'sta!\nŠomi 8.5 - aktuelni MVP solidan uz standardno kenjanje saigračima\nAtlantid 8.5 - brojne propuštene gol prilike, ipak solidan\nĐef 8.5 - odličan, stub tima\nMoma 8.0 - gol kroz noge!!!\nDili 8.5 - trčao za trojicu!\nZoki...','N. Savić','2026-06-05 09:47:37','2026-06-05 09:47:37'),(250,1,'20','2026-01-05 19:00:00','SC Jarac','19:00','I. Radosavljević',7,10,'colored_win',1,NULL,'KAKAV POČETAK 2026. GODINE!!!\nPrednost na papiru umalo da bude opravdana, ali Šareni su ipak režirali triler dostojan Jarca!\nŠareni su i krenuli bombastično, prvo je Atlantid matirao Momu, a potom Malo povećao na 2:0.\nŠomi lepom solo akcijom pogađa precizno sa poludistance.\nAtlantid još jedanput na isti način matira Momu spuštanjem lopte isored njega u suprotni ugao. (3:1)\nNa najveću prednost od 3 gola razlike još jednim golom u situaciji 1 na 1 Atlantid  vodi svoj tim. (4:1)\nŠarene onda kao da je neko isključio i Beli prave furijski preokret sa svoja 4 gola (4:5; dominirali WH i Šomi uz odličnu podršku saigrača).\nAtlantid donosi novo izjednačenje, ali Beli opet daju gas i sa dva nova gola dolaze do prednosti od 7:5. (Golove postigli Šomi i Ćirko - zabio odlično u svom stilu sa distance.)\nOvo je situacija u 19:47h, a onda Šareni ubacuju u \"turbo mode\". Atlantid opravdava zvanje prvog nosioca Zlatnog Aristona i u kontrama uspešno upošljava saigrače Balaća i Dilija koji donose izjednačenje. (7:7)\nOvo kao da je dobrano uzdrmalo Bele kojima ni MVP nije mogao da pomogne u datim trenucima... Naprotiv! Falilo je samo glasno izrečeno \" A daaaajjj!!!\".\nZato na suprotnoj strani glavni pretedent za ovu najprestižniju nagradu gura svoj tim do pobede u fotofinišu! Čak je i podsetio na još jednog legendarnog nosioca ove titule kada je tačno u 20:00:00:00 viknuo \"KRAAAAJJJ!!!\" (što su mu neki iz suprotnog tima oštro zamerili).\nSvedočili smo odličnoj utakmici i možemo da konstatujemo ako se ovako nastavi, ostatak sezone će biti senzacionalan!!!\nAtlantid 9.5 - \"MVP! MVP! MVP!\"\nDili 9.0 - pokretna barijera, a ovog puta briljirao i u napadu\nMalo 9.5 - srce i duša Jarca!\nBuda 9.0 - odličan\nGnjidić 8.5 - dominirali su šutevi sa distance\nBalać 9.0 - odličan povratak na teren\nŠomi 9.0 - ???\nWH  9.0 - standardan\nĆirko 8.5 - \"Ma ložim vas, jači smo!\"\nĐef 8.5 - (yo)\nŠiki 8.0 - solidan\nMoma...\nPS. Zoki...','N. Savić','2026-06-05 09:47:37','2026-06-05 09:47:37'),(251,1,'21','2026-01-14 18:00:00','SC Jarac',NULL,'S. Đorđević',3,3,'draw',1,NULL,'ODLIČAN FUDBAL!!!\nNASTAVAK SEZONE ISPUNJAVA SVA OČEKIVANJA!\nIzmena neposredno pred početak očekivano je donela ujednačeniju igru na obe strane.\nŠomi vs. Atlantid, Dili vs. Ogi, Zoki...\nSve je obećavalo spektakl!\nDominantne su bile pre svega odbrane i timska igra.\nPrvi su Šareni razbilu tvrdu protivničku odbranu i preko Atlantida poveli 1:0. Đef sam u kontri uspeva da matira Zokija M. za 2:0.\nOko prvog gola Belih se vodila žestoka polemika, da li je gol regularan, da li je autogol Vatrogasca ili srećan gol od odbitka Dilija. Sve u svemu, 2:1.\nŠomi šutem iz driblinga pogađa rašlje za izjednačenje, a sličnim golom donosi vođstvo svom timu - 3:2.\nBeli su nakon ovoga parkirali autobus ispred svog gola.\nU 19:00:00 Beli su u Zeninom stilu vikali \"KRAJJJ!!!\", ali nakon konstatacije da je skoro ceo tim belih kasnio na termin i kako je tekma počela u 18:08, dogovoren je nastavak do 19:08.\nŠareni uporno napadaju, Beli se brane životom i u 19:07 Đef šalje loptu ispred protivničkog gola gde Atlantid uspeva da ubaci loptu u protivničku mrežu za konačni nerešeni rezultat od 3:3.\nOdličan fudbal, dominantne tvrde odbrane, lepa timska igra oba tima.\nPozivamo Zenu da izdelegira konačan rezultat.\nKako god, ovo je pobeda Jarcoa!!!\nŠomi 9.5 - možda i ima nade za njega u nastavku sezone\nObren 8.5 - odličan\nDili 9.0 - sveprisutni 2.0\nMalo 9.0 - stub!\nZoki M. 8.5 - odličan\nMoma...\nAtlantid 9.0 - igrao pod elanom uspešne polusezone\nĐef 9.0 - odličan na obe strane terena\nOgi 9.5 - sveprisutni!\nDraško 8.5 - solidan\nVatrogasac 7.5 - odigrao gore čak i od Zokija...\nZoki...','N. Savić','2026-06-05 09:47:37','2026-06-05 09:47:37'),(252,1,'22','2026-01-21 18:00:00','SC Jarac',NULL,'S. Đorđević',4,9,'colored_win',1,NULL,'KASNO BELI U JARAC STIŽU!\nBeli prvih pola sata kao da nisu ni postojali na terenu. Nakon što je Šomi umuvao prvi gol i potom nastavio da zabija, skor je vrlo brzo bio 6:0. Igra se nastavila i Beli uspevaju preko Đefa da postignu prvi gol (6:1).\nŠareni nastavljaju svoju dominaciju sa dva nova gola (8:1).\nBeli uspevaju da se konsoliduju i da preko Đefa, Atlantida i Tonija smanje na 8:4. Ovo je tek neznatno zatreslo gaće aktuelnom MVP koji u poslednjem minutu postiže svoj 6. gol za konačnih 9:4.\nDa su Beli igrali od starta kao što su odigrali drugu polovinu meča, verovatno da bi sve bilo drugačije... Sve u svemu - dobar fudbal i šareni zasluženo odneli 3 boda!\nŠomi 10.0 - danas izuzetno precizan i efikasan\nDili 9.0 - sveprisutni\nMladen B. 9.0 - odličan i u odbrani i u napadu\nNedim 9.0 - Ronaldo u elementu\nVatrogasac 8.5 - (do_not_enter)\nBuda 9.0 - odličan\nAtlantid 8.0 - eh\nĐef 8.0 - ahil\nOgi 8.0 - bogovi brzine mu nisu bili naklonjeni vcrs\nObren 8.5 - trud i upornost\nZoki 8.5 - ministar odbrane\nToni 8.0 - van forme\nPS. Vrati se Zoki...','N. Savić','2026-06-05 09:47:37','2026-06-05 09:47:37'),(253,1,'23A','2026-01-28 17:00:00','SC Jarac','17:00','N. Radosavljević',6,5,'white_win',1,NULL,'Dvorana Jarac | 28.1.2026 | 17:00\nU dvorani Jarac viđen je dinamičan i borben meč između ekipa BELI i ŠARENI, sa dosta tempa, kontri i dobrih duela. Ekipa BELIH je od starta nametnula ritam, a Spaskovski je bio apsolutni lider – het-trik i konstantna pretnja po gol ŠARENIH.\nBELI su brzo poveli (1:0 u 17:12), zatim preko dobre saradnje Bundalo–Spaskovski povisili na 2:0. ŠARENI se vraćaju preko Ognjena Grkinića (Ogi), ali Spaskovski ubrzo u kontri vraća +2 (3:1).\nNakon kratkog zatišja i čuvenog “stali smo”, Mali koristi grešku i diže na 4:1. Do kraja, Šika smanjuje na 4:2, ali BELI rutinski privode meč kraju. Vredi pomenuti i stativu Bundala, kao i nekoliko “TX” momenata na obe strane.\nPosle već viđenog ritma i prednosti BELIH (4:2), usledilo je i drugo čuveno „Stali smo!“, koje je nakratko unelo konfuziju – ali i golove.\nMladen Bundalo koristi prostor i u 17:48 matira Zokija TX za 5:2, delovalo je da je meč rešen. Međutim, ŠARENI tada ubacuju u višu brzinu:\nnajpre Gnjidić smanjuje na 5:3 posle asistencije Šike, a već minut kasnije Ogi pogađa za 5:4 i vraća totalnu neizvesnost.\nIpak, BELI brzo reaguju – Veljavi postiže pogodak za 6:4 u 17:51, na asistenciju raspoloženog Bundala, čime je praktično stavljena tačka na utakmicu.\nMeč je završen uz visok tempo, serije golova i kratke padove koncentracije, ali uz zasluženu pobedu ekipe BELI.\nKonačan rezultat:\nBELI 6 : 4 ŠARENI\nStatistika strelaca i asistencija\nSpaskovski – 3 gola\nMali – 1 gol\nBundalo M. – 1 gol + 3 asistencije ⭐\nVeljavi – 1 gol\nVatrogasac – 1 asistencija\nOgi – 2 gola\nŠika – 1 gol + 1 asistencija\nGnjidić – 1 gol\nIzveštaj: N. Savić/chatGPT (izveštaj načinjen pre kraja meča i pogotka Šarenih za konačnih 6:5)',NULL,'2026-06-05 09:47:38','2026-06-05 09:47:38'),(254,1,'23B','2026-01-28 18:00:00','SC Jarac','18:00','S. Đorđević',4,3,'white_win',1,NULL,'MAT U POSLEDNJEM POTEZU!\nMože se reći da je tempo bio ubitačan. Timska igra, neizvesnost do kraja i epilog u poslednjoj sekundi!\nBeli su krenuli dosta opasnije i to realizovali golovima Nedima koji je bio izuzetno raspoložen za igru, i Ogija (koji je i pored odigranog meča u terminu ranije nastavio u istom ritmu). Nikola B. je bio izuzetno opasan po gol protivnika, kao i Atlantid koji je imao svoje šanse.\nPrednost od 3:0 koju su Beli držali od 18:20h, Šomi iz 100og pokušaja u stilu Veljavog uspeva da umuva loptu u gol i smanji rezultat na 3:1.\nWH smanjuje na 3:2, a onda nekih 5min pred kraj Moma zbunjuje Zokija šutem (ili možda pasom?! (hmm)), i lopta završava u mreži za 3:3.\nBeli su krenuli svim snagama u napad, što su Šareni koristili u kontrama (WH i Šomi konstantno kampovali na protivničkoj polovini), ali Beli su na golu imali jednog jedinog Zokija M. - ministra odbrane! Nepremostiva prepreka za šareni tim (sem kad ga je Moma iznenadio šutom ili pasom?!? (hmm)).\nPoslednji trenuci meča... U vazduhu upljuvane sale Jarca opori oznoje vazduh moga se seći nabojem koji se prenosio sa parketa. 10... 9... 8...\nNa pola terena lopta se namešta jednom buckastom igraču...\n7... 6... 5...\nNoga mu se zateže na šut...\n4...\nTuđa patika raspaljuje po lopti...\n3...\nLopta u vidu torpeda je poletela ka golu šarenih...\n2...\nMomi lopta prolazi kroz noge i završava u mreži...\n1...\n0...\nKRAJ!!!\nKakav meč!!!\nNedim igrač utakmice!\nMomu usrao gol...\nĐef, bravo za podelu!\nŽiveo Jarac!!!\nNedim 10.0 - perfektna partija\nIgnjatović 8.5 - odlična prva partija u dvorani Jarac\nZoki M. 9.5 - spasitelj\nAtlantid 8.5 - solidan\nNikola 9.0 - mladost!\nOgi 9.0 - odličan\nŠomi 8.5 - onako\nDili 8.5 - oktopod\nWH 8.5 - odlican\nMoma 9.0 - najbolji igrac sarenih!\nKutni 8.5 - dok nije umirao na terenu... Odlican\nĐef 8.5 - bravo!\nPS. Zoki...','N. Savić','2026-06-05 09:47:38','2026-06-05 09:47:38'),(255,1,'24A','2026-02-04 17:00:00','SC Jarac','17:00','N. Radosavljević',9,12,'colored_win',1,NULL,'ŠARENI SNIMILI ROKI VII I ROKI VIII U JEDNOM TERMINU!!!\nUspeli su da se vrate iz čak dva nokdauna!\nBeli su brzopotezno (i malo pogurani Fortunom) došli prednosti od 4:0. Šareni uspeli da umuvaju prvi gol (4:1). Beli povećavaju (5:1), Šareni uspevaju jos jedan da zabiju (5:2), ali su Beli delovali totalno neumoljivo i predvođeni pre svega Budom dolaze do 6:2.\nA onda prebijeni Šareni (zamislite muziku iz Rokija u pozadini) kreću da ređaju \"kontraudarce\" i uspevaju da smanje na 6:5.\nBeli su delovali smušeno za trenutak, ali uspevaju da povrate svoju igru i preko WH-a i Šomija dolaze do nove velike razlike (9:5).\nŠarenima, koji su se opet našli na konopcima, se u mislima pojavila  Adrian i Šika koji ih tera da uhvate kokošku i govori \"Legendo, ti si legenda, dođi u Jarac!!!\"...\n(Sad kreće \"Eye of the tiger\"!)\nDam   dam dam dam   dam dam dam     dam dam daaaaaaaam\nŠareni predvođeni Atlantidom i Spaskovskim kreću da pune protivnike!!!\nDam dam dam... 9:9\nBeli ne znaju šta ih je snašlo. Pokušavaju pošto poto da vrate prednost, što Beli pametno koriste i iz kontre dolaze do prve prednosti na meču u par minuta pred kraj, a onda sa još dve munjevite kontre da u potpunosti matiraju protivnika.\nKAKAV PREOKRET!\nNeki čak svedoče da su videli i Šikoa iznerviranog...\nAli iako nismo verovali u Maloovu podelu - alal kurac!\nŽIVEO JARAC!\nAtlantid 9.8 - treća partija u sezoni sa 8 golova\nSpaskovski 9.8 - odličan\nMalo 10.0 - srce i duša tima\nSiniša 8.9 - odličan\nVatrogasac...\nBuda 9.0 - odlicna partija\nWH 8.9 - standardno dobar\nŠika 8.4 - dobar\nObren 8.4 - Ogi sa stomakom\nŠomi ?\nBonus:\nAtlantid 8:1 Šomi (yo)\nIzveštaj: N. Savić',NULL,'2026-06-05 09:47:38','2026-06-05 09:47:38'),(256,1,'24B','2026-02-04 18:00:00','SC Jarac','18:00','N. Radosavljević',7,4,'white_win',1,NULL,'Beli – Šareni 7:4 (SC Jarca)\nNa terenu SC Jarca viđena je prava goleada i još jedna Gnjidićeva partija za udžbenike, uz dosta lepih poteza, malo nervoze i poneku sudijsku „slabovidost“.\nBeli su bolje otvorili meč i poveli već u ranoj fazi – Gnjidić je doneo prednost pogotkom za 1:0, na asistenciju Nikole B. Šareni su brzo odgovorili, Zoki je izjednačio na 1:1, uz asistenciju Bundala, ali je to bio samo kratki prekid u naletu Belih.\nUsledila je serija golova kojom su Beli praktično rešili utakmicu. Gnjidić pogađa sa distance za 2:1, zatim Ogi povećava na 3:1 posle lepe asistencije Moše, a upravo Moša ubrzo vraća asistenciju Ogiju i pogađa za 4:1.\nKljučni trenutak meča dolazi kod gola za 5:1 – Gnjidić koristi asistenciju Vujadina praktično sa polovine terena i potvrđuje da mu je ovo veče „ono pravo“. Nedugo zatim stiže i 6:1, još jedan projektil Gnjidića sa distance, čime je kompletirao četiri gola i potpuno prelomio duel.\nŠareni se ipak nisu predali. Šomi, legendarni MVP Jarca, postiže prelep gol – šut iz kolena pravo u rašlje za 6:2, što je izmamilo aplauze i protivničke ekipe. Zoki zatim dodaje još jedan pogodak za 6:3, doduše uz dosta kontakta i faul u napadu koji sudija nije registrovao, pa je ostalo mesta za raspravu.\nIpak, svaku dilemu gasi Nikola B. fantastičnim solo prodorom i golom za 7:3. Do kraja je Nedim samo ublažio poraz Šarenih na 7:4, posle malo „petljanja“, ali dovoljno da lopta završi u mreži.\nPosebno treba pomenuti Vujadina, koji je doduše „zasrao“ dva zicera, ali je ponovo potvrdio da zna kako se igra protiv MVP-jeva – četvrta pobeda protiv njih ide na njegov konto.\nЗашто у извештају нема да сам успео с целог терена да избацим лопту из херметички затворене сале?! ?\nPrimedba na izveštaj: O. Grkinić','M. Korunović/chatGPT','2026-06-05 09:47:38','2026-06-05 09:47:38'),(257,1,'25A','2026-02-11 17:00:00','SC Jarac','17:00','M. Korunović',8,8,'draw',1,NULL,'NEIZVESNOST, PREOKRETI I ZA KRAJ NEREŠEN REZULTAT! JARAC!!!\nNakon uvodnog odmeravanja, prvi je mrežu pogodio Siniša. Ubrzo je na drugoj strani Malo izjednačio.\nU dvadesetom minutu Šomi kupi odbitak nakon jakog Vatrogaščevog šuta i pogađa za novo vođstvo svog tima (2:1).\nŠomi povećava vođstvo na 3:1, a potom asistira Atlantidu koji pogađa za 4:1. Vatrogasac sa pola terena neverovatno lobom pogađa prazan gol za velikih 5:1.\nAli šta je zapravo velika prednost u Jarcu???\nMalo to najbolje zna i poveo je svoj tim u juris koji sa tri brza gola smanjuju na 5:4.\nAtlantid novim golom tek za trenutak održava prednost (6:4).\nA onda preokret - Nikola B. i Spaskovski pogađaju mrežu do rezultata 8:6. Ostalo je svega 8min do kraja. Šareni kao da su potpuno potonuli, ali onda izranja Atlantid koji matira golmana u dve brze kontre i donosi novo izjednačenje (ispostaviće se i konačan rezultat 8:8). U poslednja 2min oba tima su pokusali da preotmu pobedu, ali je oznacen kraj i Mali se izvukao bez napusavanja kurcem...\nSve u svemu - odličan meč!\nAtlantid 9.5 - 4:2\nŠomi 9.2 - 2:4\nMoša 8.8 - ??\nŠika 8.6 - dobar\nVatrogasac 8.9 - solidan\nSiniša 9.0 - odličan\nNikola B.  9.0 - eh mladosti\nSpaskovski 8.8 - solidan\nMalo 8.9 - ?\nPavle 8.5 - eh mladosti\nDuci 8.8 - dobar\nMilan M. 8.6 - za prvi put top\nIzveštaj: N. Savić',NULL,'2026-06-05 09:47:38','2026-06-05 09:47:38'),(258,1,'25B','2026-02-11 18:00:00','SC Jarac','18:00','S. Đorđević',8,6,'white_win',1,NULL,'Izveštaj ukratko:\n*Gnjidic u 17.minutu tuširanja:\n“VRHUNSKI FUDBAL !!! STO VOLIM OVAKVE FUDBALE !!!”\n*dao 4 gola','S. Đorđević','2026-06-05 09:47:38','2026-06-05 09:47:38'),(259,1,'26A','2026-02-18 17:00:00','SC Jarac','17:00','I. Radosavljević',6,5,'white_win',1,NULL,'[ sreda, 18. februar 2026. 17:18 ] Miloš Nikolić: 1:0 beli\n[ sreda, 18. februar 2026. 17:18 ] Miloš Nikolić: Spaskovski postigao prelep gol\n[ sreda, 18. februar 2026. 17:27 ] Miloš Nikolić: 2:0 za bele - Vlada (valjda)\n[ sreda, 18. februar 2026. 17:29 ] Miloš Nikolić: 2:1 Obren prelepim golom kroz noge smanjuje\n[ sreda, 18. februar 2026. 17:30 ] Miloš Nikolić: 3:1 Spaskovski\n[ sreda, 18. februar 2026. 17:35 ] Miloš Nikolić: 3:2 za bele, Ogi postiže pogodak iz prelepe akcije\n3:3 Toni\n4:3 za bele, Gandra prelep pogodak\n[ sreda, 18. februar 2026. 17:48 ] Nikola Radosavljević: Ovom novom izveštaču sve prelepo...\n[ sreda, 18. februar 2026. 17:54 ] Miloš Nikolić: 4:4 prelep gol Jovana Marjanovića(14)\n4:5 Ogi prelepim golom donosi prednost šarenima\n[ sreda, 18. februar 2026. 17:57 ] Miloš Nikolić: 5:5 GANDRAAA, prelepoooo\n6:5 GANDRAAA u zadnjem minutu\n[ sreda, 18. februar 2026. 18:00 ] Miloš Nikolić: Prelepo ljudi moji, kakva utakmica\nIzveštaj: M. Nikolić',NULL,'2026-06-05 09:47:38','2026-06-05 09:47:38'),(260,1,'26B','2026-02-18 18:00:00','SC Jarac','18:00','S. Đorđević',9,9,'draw',1,NULL,'Izveštaj ukratko:\n- ŠARENI prave seriju 3:0\n- Zoran kreće da kenja\n- BELI prave seriju 8:0\n- Zoran prestaje da kenja\n- Šomi pravi seriju 5:0\n- Zoran naručuje pomfrid telefonom.\nOdličan fudbal.','S. Đorđević','2026-06-05 09:47:38','2026-06-05 09:47:38'),(261,1,'27A','2026-02-25 17:00:00','SC Jarac','17:00','N. Radosavljević',14,8,'white_win',1,NULL,'Po podeli timovi znatno izmenjeni, a poseban hendikep je bio izostanak G. Đinđića koji se samo nije pojavio, tako da je podela bila izrazito nebalansirana.\nU efikasnoj i dinamičnoj utakmici ekipa Šarenih ostvarila je ubedljivu pobedu nad Belima rezultatom 14:8. Od samog početka meča Šareni su nametnuli visok tempo igre, agresivan presing i bolju realizaciju, što je na kraju i presudilo.\nNajefikasniji pojedinac susreta bio je Šomi, koji je sa čak šest pogodaka još jednom potvrdio svoju konstantnu formu i dominaciju na terenu. Njegova kretnja bez lopte, preciznost u završnici i kontrola ritma igre predstavljali su ključnu prednost Šarenih.\nZnačajan doprinos dali su i:\n•	Gnjidić (4 gola) – konstantna pretnja po gol protivnika\n•	Vatrogasac (2 gola) – borben i čvrst u duelima, sa nekoliko oštrih uklizavanja koja su dodatno podigla tenziju u redovima Belih\n•	Duca (2 gola) – siguran u završnici i taktički disciplinovan\nU redovima Belih istakao se Atlantid sa tri pogotka, ali uprkos solidnoj individualnoj partiji, ekipa nije uspela da uhvati rezultatski priključak. U pojedinim momentima frustracija je bila vidljiva, pa je Atlantid u naletu nezadovoljstva čak razmatrao napuštanje terena.\nPogotke za Bele postigli su još:\n•	Spaskovski (1)\n•	Šika (1)\n•	Obren (1, uz 2 neiskorišćene prilike)\n•	Draško (1, uz 0 realizovanih dodatnih pokušaja)\nUtakmicu je obeležila čvrsta igra i visok intenzitet, posebno u duelima gde je Vatrogasac agresivnim uklizavanjima uspevao da izbaci protivnike iz ritma, što je dodatno pojačalo nervozu u ekipi Belih.\nNa kraju, Šareni su zasluženo slavili, potvrdivši bolju organizaciju, veću efikasnost i individualni kvalitet u ključnim momentima susreta.','M. Nikolić/chatGPT','2026-06-05 09:47:38','2026-06-05 09:47:38'),(262,1,'27B','2026-02-25 18:00:00','SC Jarac','18:00','S. Đorđević',10,5,'white_win',1,NULL,'Egal utakmica do pola, i onda potop Belih… 3 lagana gola primljena za svega 2 minuta su ukanalili Bele, sto su Šareni iskoristili i održali prednost do kraja. Vrhunska igra mladog i starog Bundala, i iznenadjujuce malo gresaka Zokija Tri Tacke.\nMrzi me da dajem ocene, Djef pusi kurac.\nNešto se ne uklapa u izveštaju i rezultatu...ko se ukanalio, ko je šta održavao do kraja...\nSve je suprotno od oboga što jeste...\ni da li je onda Zoki... iznenađujuće malo ili mnogo grešio\nKomentar na izveštaj: M. Korunović','S. Đorđević','2026-06-05 09:47:38','2026-06-05 09:47:38'),(263,1,'28A','2026-03-04 17:00:00','SC Jarac','17:00','S. Đorđević',11,5,'white_win',1,NULL,NULL,NULL,'2026-06-05 09:47:39','2026-06-05 09:47:39'),(264,1,'28B','2026-03-04 18:00:00','SC Jarac','18:00','S. Đorđević',8,5,'white_win',1,NULL,'Napomena: Po samostalnom nabrajanju golova, zbir golova Belih je za jedan veći od ukupnog broja golova ekipe.',NULL,'2026-06-05 09:47:39','2026-06-05 09:47:39'),(265,1,'29A','2026-03-11 17:00:00','SC Jarac','17:00','S. Đorđević',6,5,'white_win',1,NULL,'PRVI TERMIN: MLADOST VS. ISKUSTVO... IPAK, BEZ STARCA NEMA UDARCA!\nBeli u poslednjem minutu meča otimaju sva tri boda!!!\nBeli su i uspešnije otvorili meč kada je Atlantid uposlio Šomija za prvo vođstvo na meču. Mladi i perspektivni Nikola B. igrao je simultanke (saigraci su ga hranili loptama) i sa tri gola donosi osetniju prednost svom timu - 3:1. Atlantid još jedanput uspešno šalje loptu ka Šomiju koji opet uspešno matira protivničkog golmana za 3:2. Šomi u narednom napadu uspešno upošljava Pavla R. koji postiže gol za izjednačenje - 3:3.\nPavle uzvraća asistencijom za Šomija koji donosi prvu prednost svom timu (4:3).\nNikola B. ponovo pogađa za novo izjednačenje (4:4).\nDuca šutem sa poludistance na Šomijevu asistenciju ponovo donosi prednost Belima (5:4).\nNikola B. je definitivno odigrao jednu od najboljih partija što je pokazao i svojim četvrtim golom koja je bila prava majstorija - driblinzima ispred protivničkog gola izbacio odbranu i golmana i samo je plasirao loptu u gol (5:5).\nIgrao se poslednji minut kada je Malo istrčao u napad i glavom uspeo da spusti loptu u senstaesterac gde je Atlantid uspeo da se snadje i posalje loptu u nebranjeni ugao. Iako je Šomi dao više golova, Atlantid je pogodio kada je bilo najteže!\nBeli pobeđuju!\nŠomi 9.0 - dobio bi mozda i vecu ocenu, ali kenjao saigracima\nDuci 8.8 - odlican\nMalo 9.5 - stub tima i krucijalan za pobedu svog tima\nPavle 8.6 - odlican gol dao i stamen u odbrani\nAtlantid 8.8 - proigravao, bio opasan i kad je bilo najbitnije zabio za pobedu!\nNikola B. 10.0 - iako u porazenom timu, odigrao mec za cistu 10ku\nVatrogasac 8.0 - svi zivi!\nBogdan 8.5 - solidan\nSiniša 8.5 - jaja na broju!\nŠiko 8.0 - izostalo je njegovih špicoka\nIzveštaj: N. Savić',NULL,'2026-06-05 09:47:39','2026-06-05 09:47:39'),(266,1,'29B','2026-03-11 18:00:00','SC Jarac','18:00','S. Đorđević',6,11,'colored_win',1,NULL,'- Utakmica između Belih i Šarenih završila je rezultatom 11:6 u korist Šarenih, uz izvanredne nastupe igrača kao što su WH i Nikola B.\n- Beli su imali vođstvo tokom meča, ali su Šareni preokrenuli rezultat u drugom delu, zahvaljujući efikasnoj igri i asistencijama.\n- Igrači su komentarisali performanse, ističući ključne trenutke i pojedinačne uspehe, dok su se zabavljali i razmenjivali šale o igri.\nVeze nema...pomešao dve tekme, ali nebitno je...ima izveštaja\nNapomena: Nedostaju podaci o strelcima jednog gola Šarenih i dva gola Belih.','M. Korunović/chatGPT','2026-06-05 09:47:39','2026-06-05 09:47:39'),(267,1,'30A','2026-03-18 17:00:00','SC Jarac','17:00','N. Savić',1,16,'colored_win',1,NULL,NULL,NULL,'2026-06-05 09:47:39','2026-06-05 09:47:39'),(268,1,'30B','2026-03-18 18:00:00','SC Jarac','18:00','S. Đorđević',6,2,'white_win',1,NULL,NULL,NULL,'2026-06-05 09:47:39','2026-06-05 09:47:39'),(269,1,'31A','2026-03-25 17:00:00','SC Jarac','17:00','I. Radosavljević',9,7,'white_win',1,NULL,'- Огњен је известио о резултатима утакмица, укључујући голове и асистенције играча.\n- На крају утакмице, резултат је био 9:7 у корист БЕЛИХ, са значајним учинком играча као што су Шоми и Недим.\n- Након тога, Неманја је обавестио о резултату утакмице ШАРЕНИ против Атлантида, где су Шарени водили 2:0.\nIzveštaj: M. Korunović/chatGPT',NULL,'2026-06-05 09:47:39','2026-06-05 09:47:39'),(270,1,'31B','2026-03-25 18:00:00','SC Jarac','18:00','S. Đorđević',6,4,'white_win',1,NULL,'Zoki… TX-u se osladile pobede\nU efikasnoj i na momente vrlo uzbudljivoj utakmici, ekipa Belih savladala je Šarene rezultatom 6:4, potvrdivši dobru formu i seriju pozitivnih rezultata.\nBeli su od samog starta nametnuli ritam i brzo stavili do znanja protivniku da ih zanima samo nastavak pobedničkog niza. Centralna figura susreta bio je nezaustavljivi WH, koji je čak pet puta zatresao mrežu i praktično sam rešio pitanje pobednika. Njegovu partiju odlično je ispratio i Zoki TX, koji je dodao jedan pogodak, ali i bio važan faktor u organizaciji igre.\nSa druge strane, Šareni su pružili solidan otpor, ali nisu imali rešenje za raspoloženog protivnika. U listu strelaca upisali su se Ćirko, Ogi, Đef i Drasko, svaki po jednom, što dovoljno govori o raspodeli odgovornosti u napadu, ali i o nedostatku konkretnijeg završetka.\nVažan doprinos pobedi Belih dao je i Dili, koji se nije upisao među strelce, ali je zabeležio asistenciju i učestvovao u kreiranju akcija koje su lomile protivničku odbranu.\nNa kraju, Beli su zasluženo slavili, dok Šarenima ostaje da analiziraju propuste, posebno u defanzivi, jer su primili čak šest golova. Forma ekipe predvođene Zokijem TX očigledno je u usponu – a kako stvari stoje, pobede su im se i te kako “osladile”.','M. Korunović/chatGPT','2026-06-05 09:47:39','2026-06-05 09:47:39'),(271,1,'32A','2026-04-01 17:00:00','SC Jarac','17:00','N. Radosavljević',6,5,'white_win',1,NULL,'Napomena: Nije upisan strelac jednog gola za ekipu Šarenih.',NULL,'2026-06-05 09:47:39','2026-06-05 09:47:39'),(272,1,'32B','2026-04-01 18:00:00','SC Jarac','18:00','S. Đorđević',3,10,'colored_win',1,NULL,NULL,NULL,'2026-06-05 09:47:39','2026-06-05 09:47:39'),(273,1,'33A','2026-04-08 17:00:00','SC Jarac','17:00','S. Đorđević',5,12,'colored_win',1,NULL,'Након уводних 10 минута тврде игре без погодака, новајлија Кишињев се добро сналази и постиже погодак. Само напад или два касније Никола окреће неколико противничких играча  и оставља лопту Малом на шут са велике удаљености који смешта у сâм угао гола шарених. Шарени затим имају неколико прилика које је све осујетио Синиша на голу. Осим тога су погодили и једну стативу.\nСиниша покушава да предрибла Спасковског, али му се лопта запетљава у ногама и Спасковском остаје лак посао да смести лопту у небрањену мрежу. 2:1.  Бели се поново враћају одмах после примљеног поготка. Мали узвраћа асистенцију Бундалу који шутира снажно по земљи и пролази голману кроз ноге. 2:2.\nБели имају 1 на 1. Ватрогасац брани Николин шут. Шоми шаље фантастичну лопту преко целог терена. Кишињев ју је прихватио у маниру Бербатова и постигао погодак за ново вођство шарених. Бели се поново враћају у живот одмах по примљеном голу. Обрен оставља петом за Николу који још једном шутира снажно и прецизно. Три сви. У међувремену неколико добрих прилика на обе стране међу којима се истиче Шомијева 1 на 1 и одлична одбрана Малог.\nКишињев је проиграо Спасковског који промашује стопостотну прилику. Исти играч намешта прилику и Шомију, али поново без успеха. Пола сата је прошло. Појачава се интензитет фудбала, али и тензија на терену коју потпаљују споре одлуке Ватрогасца. Бели имају две одличне прилике. Никола погађа стативу, затим Обренов шут брани Шика. Већ у следећем нападу иде брза контра шарених. Комбинација Шоми-Кишињев-Шоми доноси и четврту предност шаренима.\nПавле два напада заредом спасава свој гол правовременим реакцијама.\nНевероватно, али се бели и четврти пут враћају и то поново преко Никола² тандема - Мали за Бундала.\nБели никако да дођу до предности. Синишин ударац завршава на левој стативи Ватрогашчевог гола. Нешто јачи прекршај Павла над Шикосављевићем сениором. Након Обренове погрешне повратне, Спасковски шаље лепу лопту преко одбране белих. Кишињев одлично прихвата пас и добро шутира, али Мали рефлексно интервенише. И то се дешава - бели стижу први пут до вођства. Обрен шаље добру дугу лопту по земљи, а Никола Б. у свом стилу окреће чувара и смешта лопту кроз ноге ватрогасном голману. Дуго је трајала опсада гола белих. Мали узалуд опомиње саиграче да изађу. То доводи до двају карамбола из којих Спасковски оба пута излази као стрелац. Први пут му је лопту додао Шика, други Кишињев. Брзи преокрет - 6:5 за шарене.\nБели излазе високо. Шоми осваја лопту испред свог гола. Шева једног, другом протура кроз ноге и избија у један-на-један ситуацију коју рутински решава боцнувши лопту.\nБели су пали физички. Шоми шаље још једну дугу лопту преко комплетне одбране коју прихвата Спасковски и постиже свој нови погодак. Највећа предност досад. Бели се подижу и организују неколико добрих напада уз нешто слабија покривања у одбрани. Шоми врши два орешник атентата над Синишом. Срећом, оба пролазе поред главе голмана белих.\nКвалитет шарених још једном долази до изражаја. Шоми упошљава  Спасковског који једноставно решава противника и смешта лопту кроз ноге голмана. Бели погађају пречку на којој се налазила Шикина рука, али је, рекло би се, добро прошао. Ватрогасац уклизава Николи Б. Иако не сасвим безопасно, било је чисто на лопту. Сјајна лопта Николе Б. за Обрена чији ударац зауставља Шика. У следећем нападу Никола Б. обезбеђује добрим дриблинзима нову шансу пред голманом, али Шика не наседа на дриблинг и одлично брани. Већ у следећем нападу шарени кажњавају промашаје, а Шоми враћа асистенцију Спасковском. 11:5. Шика шаље изванредну лопту, а ударац Кишињева брани Синиша. Исти играч брани још један ударац, али не успева и трећи. Спасковски постиже погодак без асистента за 12:5. Шоми промашује 1-на-1 за крај првог термина. Бели су имали снаге за првих пола сата, али је квалитет уз искуство било на страни шарених.\nIzveštaj: O. Grkinić',NULL,'2026-06-05 09:47:40','2026-06-05 09:47:40'),(274,1,'33B','2026-04-08 18:00:00','SC Jarac','18:00','S. Đorđević',2,2,'draw',1,NULL,'Izveštaj sa utakmice: Šareni – Beli 14:11\nMeč je počeo iznenađujuće – Beli su bolje ušli u igru i brzo poveli sa 2:0, najavivši da neće biti lak protivnik. Delovalo je da drže konce u rukama, ali onda sledi potpuni preokret.\nŠareni ubacuju u višu brzinu, predvođeni raspoloženim Šomijem, i serijom golova okreću rezultat na čak 6:2. U tom periodu dominiraju u svim segmentima – agresivniji su, konkretniji i efikasniji.\nBeli uspevaju da se trgnu i smanje na 6:4, vraćajući nadu da bi mogli da se vrate u meč. Međutim, to je bio njihov poslednji ozbiljniji nalet.\nUbrzo zatim, Šareni ponovo preuzimaju potpunu kontrolu i novom serijom odlaze na 10:4, praktično rešivši pitanje pobednika. Taj deo utakmice bio je presudan – razlika je postala prevelika.\nU završnici se igralo “gol za gol”, bez većih promena u odnosu snaga. Ipak, Zoki u finišu blista i sa tri uzastopna gola ublažava poraz Belih, dok se u strelce upisuje i Draško za konačnih 14:11.\nZaključak:\nŠareni su prelomili utakmicu sredinom prvog dela i početkom drugog, kada su napravili ključnu razliku. Beli su imali dobar start i solidan finiš, ali nedovoljno kontinuiteta da ozbiljnije ugroze protivnika.\nКључ утакмице: Шоми је практично сам преломио меч са 9 голова. Код Белих се више играча уписало, али није било неког ко је доминирао као он.\nNapomena: Gornji izveštaj je u potpunosti neistinit. Pravi rezultat utakmice bio je 2:2.','M. Korunović/chatGPT','2026-06-05 09:47:40','2026-06-05 09:47:40'),(275,1,'34A','2026-04-15 17:00:00','SC Jarac','17:00','I. Radosavljević',5,10,'colored_win',1,NULL,NULL,NULL,'2026-06-05 09:47:40','2026-06-05 09:47:40'),(276,1,'34B','2026-04-15 18:00:00','SC Jarac','18:00','S. Đorđević',8,6,'white_win',1,NULL,NULL,NULL,'2026-06-05 09:47:40','2026-06-05 09:47:40'),(277,1,'35','2026-04-22 18:00:00','SC Jarac','18:00','S. Đorđević',3,4,'colored_win',1,NULL,'Poslednja zvanična utakmica u sezoni održana je na dan zapečaćivanja kafane Jarac, iz razloga pravno-kriminalne prirode, dok je i dalje bilo moguće ući u dvoranu, ali je vanrednost situacije bila oličena ispijanjem pića nakon fudbala u upitno legalnim uslovima depandansa polusprata svlačionice sale Jarac. Nedelju dana kasnije, 29.4.2026, uoči već dogovorenog 36. termina u sezoni, obezbeđenje UKCS zapečatilo je i ulaz u samu salu Jarac, čime je faktički prevremeno završena sezona 2025/26. Jarac je ostao zapečaćen naredna 42 dana, u međuvremenu su igrani nezvanični fudbali u balonu Maestro (Vareška ulica u Rakovici), ali ovi fudbali nisu uvršteni u zvaničnu statistiku. Jarac je zvanično otpečaćen po odluci suda 28.5.2026, kada je održan veliki vanredni povratnički fudbal, koji je organizovan istog dana, iznenadno, u terminu od 20h, i koji je trajao sat i po, sa 14 igrača. Ovaj termin ne ulazi u zvaničnu statistiku, ali je pribeležen iz razloga istorijskog značaja.','N. Radosavljević','2026-06-05 09:47:40','2026-06-05 09:47:40'),(278,1,'JARACRES','2026-05-28 20:00:00','SC Jarac','20:00',NULL,8,12,'colored_win',0,NULL,'POVRATAK OTPISANIH I ĐEF PUŠI KURAC!!!\nKakve lepote i uzvišenog osećaj nakon povratka u groteskno ispljuvanu salu Jarac.\nNeka svetla reflektora nisu radila. Nema veze...\nKlima nije radila... Ma nema veze!\nTople vode posle 5min tusiranja nestalo... Ma nema veze!!!\nNavikli smo da se mucimo ovim, nista drugo nas ne boli.\nSama tekma je u pocetku delovala tvrdo. Dobrih uvodnih po sata rezultat je bio 0:0. Onda su Šareni prvi uspeli da zatresu mrežu preko braće O&O. 2:0\nBeli preko Vatrogasca smanjuju na 2:1.\nŠareni su delovali neumoljivo te se odlepiše na 4:1. Dili evrogolom sa distance smanjije na 4:2. Đef je takođe bio vidno raspoložen i zabija za 5-2, Zoki M. povecava na 6-2, a Obren na 7:2.\nKonstantno odmahivanje rukama onog vašeg MVP-a za trenutak je prekinuo Moma koji je pozeleneo i uneo i loptu i Zokija M. u gol.\nBeli su uspevali tek prividno da se približe nadmoćnijim protivnicima, ali su Šareni uspevali da održe značajnu prednost do kraja meča.\nPrštalo je duelima, osećala se ta želja da se nekom najebeš svega zbog uskraćenog kvalitetnog proverenog vremena u ovoj grotesknoj sali...\nSrećan povratak (svima koji slave) i ĐEF, PUŠI KURAC!!!\nPS. Zoki...\nIzveštaj: N. Savić',NULL,'2026-06-05 09:47:40','2026-06-05 09:47:40');
